        return loanJpaRepository.findById(loanId).map(loanMapper::toDomain);
    }

    @Override
    public long countActiveLoansByMember(UUID memberId) {
        return loanJpaRepository.countByMemberIdAndReturnedAtIsNull(memberId);
    }

    @Override
    public List<ActiveLoanView> loadActiveLoans(UUID memberId, int page, int size) {
        return loanJpaRepository.findActiveLoans(memberId, PageRequest.of(page, size)).stream()
                .map(row -> new ActiveLoanView(row.getLoanId(), row.getBookId(), row.getTitle(),
                        row.getLoanedAt(), row.getDueAt()))
                .toList();
    }
