import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class MemberLoansIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void listing_active_loans_returns_200_with_title_and_dates() throws Exception {
        String memberId = registerMember();
        String bookId = registerBook("Clean Code");
        loanBookOn(bookId, memberId, "2026-02-02");

        mockMvc.perform(get("/members/{memberId}/loans", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.items[0].bookId").value(bookId))
                .andExpect(jsonPath("$.items[0].title").value("Clean Code"))
                .andExpect(jsonPath("$.items[0].loanedAt").value("2026-02-02"))
                .andExpect(jsonPath("$.items[0].dueAt").value("2026-02-16"))
                .andExpect(jsonPath("$.page").value(0))
                .andExpect(jsonPath("$.size").value(20))
                .andExpect(jsonPath("$.totalCount").value(1));
    }

    @Test
    void listing_returns_only_loans_not_yet_returned() throws Exception {
        String memberId = registerMember();
        String returnedLoanId = loanBook(registerBook("Returned Book"), memberId);
        String activeBookId = registerBook("Active Book");
        loanBook(activeBookId, memberId);

        mockMvc.perform(post("/loans/{loanId}/return", returnedLoanId))
                .andExpect(status().isOk());

        mockMvc.perform(get("/members/{memberId}/loans", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.items.length()").value(1))
                .andExpect(jsonPath("$.items[0].title").value("Active Book"))
                .andExpect(jsonPath("$.totalCount").value(1));
    }

    @Test
    void listing_applies_page_and_size_while_total_count_covers_all_loans() throws Exception {
        String memberId = registerMember();
        for (int i = 0; i < 3; i++) {
            loanBookOn(registerBook("Paged Book " + i), memberId, "2026-02-0" + (i + 1));
        }

        mockMvc.perform(get("/members/{memberId}/loans", memberId).param("page", "0").param("size", "2"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.items.length()").value(2))
                .andExpect(jsonPath("$.items[0].title").value("Paged Book 0"))
                .andExpect(jsonPath("$.items[1].title").value("Paged Book 1"))
                .andExpect(jsonPath("$.page").value(0))
                .andExpect(jsonPath("$.size").value(2))
                .andExpect(jsonPath("$.totalCount").value(3));

        mockMvc.perform(get("/members/{memberId}/loans", memberId).param("page", "1").param("size", "2"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.items.length()").value(1))
                .andExpect(jsonPath("$.items[0].title").value("Paged Book 2"))
