                .andExpect(jsonPath("$[0].loanedAt").value("2026-03-10"))
                .andExpect(jsonPath("$[0].returnedAt").value(nullValue()))
                .andExpect(jsonPath("$[0].lateFee").value(nullValue()))
                .andExpect(jsonPath("$[1].loanId").value(oldLoanId))
                .andExpect(jsonPath("$[1].title").value("Clean Code"))
                .andExpect(jsonPath("$[1].loanedAt").value("2026-03-02"))
                .andExpect(jsonPath("$[1].returnedAt").value("2026-03-21"))
                .andExpect(jsonPath("$[1].lateFee").value(500));
    }

    @Test
    void history_late_fee_is_zero_when_returned_on_or_before_due_date() throws Exception {
        String memberId = registerMember();
        String loanId = loanBookOn(registerBook("On Time"), memberId, "2026-02-02");
        returnLoanOn(loanId, "2026-02-16");

        mockMvc.perform(get("/members/{memberId}/loans/history", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$[0].returnedAt").value("2026-02-16"))
                .andExpect(jsonPath("$[0].lateFee").value(0));
    }

    @Test
    void history_of_a_member_without_loans_returns_empty_array() throws Exception {
        String memberId = registerMember();

        mockMvc.perform(get("/members/{memberId}/loans/history", memberId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(0));
    }

    @Test
    void history_of_an_unknown_member_returns_404() throws Exception {
        mockMvc.perform(get("/members/{memberId}/loans/history", UUID.randomUUID()))
                .andExpect(status().isNotFound());
    }

    private void returnLoanOn(String loanId, String returnedAt) throws Exception {
        mockMvc.perform(post("/loans/{loanId}/return", loanId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"returnedAt\":\"" + returnedAt + "\"}"))
                .andExpect(status().isOk());
    }

    private String loanBook(String bookId, String memberId) throws Exception {
        return loanBookOn(bookId, memberId, null);
    }

    private String loanBookOn(String bookId, String memberId, String loanedAt) throws Exception {
        String body = loanedAt == null
                ? "{\"bookId\":\"" + bookId + "\",\"memberId\":\"" + memberId + "\"}"
                : "{\"bookId\":\"" + bookId + "\",\"memberId\":\"" + memberId + "\",\"loanedAt\":\"" + loanedAt + "\"}";
        String loaned = mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON).content(body))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(loaned).get("loanId").asText();
    }

    private String registerBook(String title) throws Exception {
        String registered = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"" + title + "\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("id").asText();
    }

    private String registerMember() throws Exception {
        String registered = mockMvc.perform(post("/members")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"name\":\"김민지\"}"))
                .andExpect(status().isCreated())
                .andReturn().getResponse().getContentAsString();
        return objectMapper.readTree(registered).get("memberId").asText();
    }
}
